class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        l = z = o = ans = 0
        for r, ch in enumerate(s):
            z += ch == '0'
            o += ch == '1'
            while z > k and o > k:
                z -= s[l] == '0'
                o -= s[l] == '1'
                l += 1
            ans += r - l + 1
        return ans

