class Solution {
public:
    int countKConstraintSubstrings(string s, int k) {
        int l = 0, z = 0, o = 0;
        long long ans = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            s[r] == '0' ? z++ : o++;
            while (z > k && o > k) {
                s[l] == '0' ? z-- : o--;
                l++;
            }
            ans += r - l + 1;
        }
        return (int)ans;
    }
};

